// Package symbols holds the sandbox child's interpreter symbol tables, generated by symgen
// (go generate ./internal/sandbox) for exactly the allow-listed packages and om, instead of
// importing yaegi's stdlib, which would link every package it wraps. Never edit the *_gen.go
// files: change symgen and regenerate; a test fails when they differ.
package symbols

import "reflect"

// Symbols are the tables by "path/name", as the interpreter's Use takes them.
var Symbols = map[string]map[string]reflect.Value{}
